import { application } from '@application'
import { loggerService } from '@logger'
import { toolApprovalRegistry, type DispatchDecision } from '@main/ai/toolApproval/ToolApprovalRegistry'

import type { AgentRuntimeEvent } from '../types'
import type { UarHostMcpBridge } from './UarHostMcpBridge'
import { createUarSecretProjection, type UarSecretProjection } from './uarSecretProjection'

const logger = loggerService.withContext('UarToolApprovalController')

type UarApprovalValue = {
  approvalId?: unknown
  admissionId?: unknown
  invocationId?: unknown
  toolCallId?: unknown
  name?: unknown
  arguments?: unknown
}

interface UarToolApprovalOptions {
  sessionId: string
  agentId: string
  runId: string
  generation: number
  principal: string
  signal: AbortSignal
  bridge: UarHostMcpBridge
  projection?: UarSecretProjection
  emit(event: AgentRuntimeEvent): void
  isClosed(): boolean
}

type PendingApproval = {
  rawApprovalId: string
  admissionId: string
  invocationId?: string
  toolCallId: string
  toolName: string
  input: Record<string, unknown>
}

export class UarToolApprovalController {
  private readonly projection: UarSecretProjection

  constructor(private readonly options: UarToolApprovalOptions) {
    this.projection = options.projection ?? createUarSecretProjection([])
  }

  abort(reason: string): void {
    toolApprovalRegistry.abort(this.options.sessionId, reason)
  }

  async handle(
    rawValue: Record<string, unknown>,
    ensureToolInput: (rawToolCallId: string, toolName: string, input: Record<string, unknown>) => string
  ): Promise<void> {
    const value = rawValue as UarApprovalValue
    if (typeof value.approvalId !== 'string' || value.approvalId.trim().length === 0) {
      throw new Error('UAR tool approval requires an exact approvalId; update the runtime before approving tools')
    }
    if (
      typeof value.toolCallId !== 'string' ||
      typeof value.name !== 'string' ||
      typeof value.admissionId !== 'string'
    ) {
      throw new Error('UAR emitted an invalid tool approval request')
    }
    const input = parseSafeActionDisplay(value.arguments, this.projection)
    const pending: PendingApproval = {
      rawApprovalId: value.approvalId,
      admissionId: value.admissionId,
      invocationId: typeof value.invocationId === 'string' ? value.invocationId : undefined,
      toolCallId: ensureToolInput(value.toolCallId, value.name, input),
      toolName: value.name,
      input
    }
    await this.prompt(pending)
  }

  private async prompt(input: PendingApproval): Promise<void> {
    const interactionState = application.get('AgentSessionRuntimeService').getInteractionState(this.options.sessionId)
    if (interactionState.userResponse === 'unavailable') {
      await this.recordAndResolve(input, false)
      return
    }
    const approvalId = `uar:${this.options.runId}:${input.rawApprovalId}`
    const presentation = interactionState.userResponse === 'stream' ? 'stream' : 'message'
    const registration = toolApprovalRegistry.registerOrReattach({
      approvalId,
      sessionId: this.options.sessionId,
      toolCallId: input.toolCallId,
      toolName: input.toolName,
      originalInput: { ...input.input },
      presentation,
      signal: this.options.signal,
      resolve: (decision) => this.dispatch(input, decision)
    })
    if (registration !== 'registered') return
    this.options.emit({
      type: 'tool-approval-request',
      request: {
        approvalId,
        toolCallId: input.toolCallId,
        toolName: input.toolName,
        input: { ...input.input },
        presentation
      }
    })
  }

  private dispatch(input: PendingApproval, decision: DispatchDecision): void {
    const interrupted =
      this.options.isClosed() || this.options.signal.aborted || decision.reason?.startsWith('UAR turn ')
    if (interrupted) {
      try {
        this.options.bridge.cancelAdmission(input.admissionId, input.invocationId, 'cancelled')
      } catch (error) {
        logger.warn('Failed to persist cancelled UAR tool admission', {
          admissionId: input.admissionId, error: this.projection.error(error)
        })
      }
      return
    }
    if (decision.approved && decision.updatedInput) {
      logger.warn('Editing tool input is not supported by the UAR runtime; rejecting', {
        toolName: this.projection.text(input.toolName)
      })
    }
    const approved = decision.approved && !decision.updatedInput
    void this.recordAndResolve(input, approved).catch((error) => {
      if (!this.options.signal.aborted && !this.options.isClosed()) {
        this.options.emit({ type: 'error', error: this.projection.error(error) })
      }
    })
  }

  private async recordAndResolve(input: PendingApproval, approved: boolean): Promise<void> {
    if (!this.options.bridge.recordHumanDecision(input.admissionId, approved)) {
      throw new Error('uar_approval_stale')
    }
    await this.resolve(input.rawApprovalId, approved)
  }

  private async resolve(approvalId: string, approved: boolean): Promise<void> {
    const response = await application.get('UarSidecarService').requestCurrent(
      `/api/uar/runs/${encodeURIComponent(this.options.runId)}/tool-approval`,
      this.options.principal,
      {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ approved, approval_id: approvalId })
      },
      this.options.generation
    )
    if (!response) throw new Error('UAR restarted before the tool approval was resolved')
    if (!response.ok) {
      const detail = this.projection.text(await response.text()).slice(0, 1_000).trim()
      throw new Error(`UAR rejected the tool approval (HTTP ${response.status})${detail ? `: ${detail}` : ''}`)
    }
  }
}

function parseSafeActionDisplay(value: unknown, projection: UarSecretProjection): Record<string, unknown> {
  let parsed: unknown = value
  if (typeof value === 'string') {
    try {
      parsed = JSON.parse(value)
    } catch {
      return {}
    }
  }
  if (!isRecord(parsed)) return {}
  const safe: Record<string, unknown> = {}
  for (const key of ['operation', 'server', 'target']) {
    const entry = parsed[key]
    if (typeof entry === 'string') safe[key] = projection.text(entry).slice(0, 512)
  }
  if (typeof parsed.detailsAvailable === 'boolean') safe.detailsAvailable = parsed.detailsAvailable
  return safe
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value)
}

//! Admission authority for selected durable jobs. Only a committed Created
//! reservation permits POST; Existing always observes the original execution.

use super::{JobDispatchError, SelectedUarJob};
use librefang_memory::task_dispatch::{SelectedClaim, SelectedJobIntent};
use crate::kernel::{subsystems::mesh::MeshSubsystemApi, LibreFangKernel};
use librefang_llm_drivers::drivers::uar_run::{UarRunClientError, UarRunControl};
use librefang_runtime::a2a::{A2aTask, A2aTaskStatus, A2aTaskStore};
use librefang_types::{
    agent::AgentId,
    uar_run::{UarDelegatedRunProjection, UarJobAttemptReservation,
        UarReservationDisposition, UarReservedJobAttempt},
};

pub(super) async fn dispatch(
    kernel: &LibreFangKernel,
    agent_id: AgentId,
    selected: SelectedUarJob,
) -> Result<UarDelegatedRunProjection, JobDispatchError> {
    validate_identity(&selected)?;
    let task = kernel.memory.substrate.task_get(&selected.job.job_id).await
        .map_err(|_| JobDispatchError::StorageUnknown)?
        .ok_or(JobDispatchError::IdentityConflict)?;
    let expected_assignee = task["assigned_to"].as_str().unwrap_or("").to_string();
    if expected_assignee != agent_id.to_string() { return Err(JobDispatchError::IdentityConflict); }
    let intent = SelectedJobIntent { job: selected.job.clone(),
        local_task_id: selected.admission.boss_task_id.clone(),
        initiating_owner: selected.verified_subject.clone(),
        workspace_id: selected.admission.workspace_id.clone(), expected_assignee };
    // The enduring intent wins against native CAS BEFORE descriptor preflight.
    let claim = kernel.memory.substrate.task_claim_selected_intent(intent.clone()).await
        .map_err(|_| JobDispatchError::StorageUnknown)?;
    let projection = dispatch_to_store(kernel.a2a_tasks(), agent_id, selected, claim).await?;
    // Separate idempotent reconciliation; a crash here leaves the original
    // private receipt intact for the next sweep, never a replacement admission.
    kernel.reconcile_selected_job(intent).await.map_err(|_| JobDispatchError::StorageUnknown)?;
    Ok(projection)
}

pub(super) async fn dispatch_to_store(
    store: &A2aTaskStore, agent_id: AgentId, selected: SelectedUarJob, claim: SelectedClaim,
) -> Result<UarDelegatedRunProjection, JobDispatchError> {
    validate_identity(&selected)?;
    match claim {
        SelectedClaim::Created | SelectedClaim::Existing => {}
        SelectedClaim::Conflict | SelectedClaim::NotFound => return Err(JobDispatchError::IdentityConflict),
        SelectedClaim::Unknown => return Err(JobDispatchError::StorageUnknown),
    }
    // Read durable authority before consulting current connection/configuration.
    // A missing retained row is an error, not an absent reservation.
    if let Some(existing) = store.get_uar_job_attempt(
        &selected.verified_subject, selected.verified_tenant.as_deref(),
        &selected.admission.workspace_id, &selected.job,
    ).map_err(storage_error)? {
        validate_existing(&selected, &existing)?;
        // Do not prepare, persist or POST refreshed input/credentials. This is
        // reconciliation, not an assertion that a changed body is an exact retry.
        return reconcile(store, &selected.control, existing).await;
    }
    if claim != SelectedClaim::Created { return Err(JobDispatchError::StorageUnknown); }
    if selected.requires_durable_restart_recovery {
        return Err(JobDispatchError::RestartRecoveryUnsupported);
    }
    let prepared = UarRunControl::prepare(&selected.admission)
        .map_err(|_| JobDispatchError::PreparationFailed)?;
    // Descriptor and binding reads have no admission effect. No native loop is
    // entered if preparation, required capability checks or persistence fail.
    let preflight = selected.control.prepare_selected_projection(
        &selected.admission, &prepared, &selected.verified_subject,
    ).await.map_err(|_| JobDispatchError::PreparationFailed)?;
    let mut pending = preflight.projection().clone();
    validate_capabilities(&selected, &pending)?;
    strip_untyped_presentation(&mut pending);
    let reservation = UarJobAttemptReservation {
        job: selected.job.clone(),
        verified_subject: selected.verified_subject.clone(),
        verified_tenant: selected.verified_tenant.clone(),
        workspace_id: pending.workspace_id.clone(),
        boss_task_id: pending.boss_task_id.clone(),
        harness: "uar".into(),
        admission_id: pending.admission_key.clone(),
        runtime_epoch: pending.runtime_epoch.clone()
            .filter(|value| !value.trim().is_empty())
            .ok_or(JobDispatchError::PreparationFailed)?,
        request_digest: prepared.request_digest.clone(),
        definition: pending.definition.clone(),
        credential_ref: pending.effective_binding.credential_ref.clone(),
        credential_revision: selected.credential_revision.clone(),
        required_capabilities: selected.required_capabilities.clone(),
    };
    let task = A2aTask {
        id: pending.boss_task_id.clone(),
        session_id: None,
        status: A2aTaskStatus::Submitted.into(),
        // Input/history can contain secrets. Non-executable presentation is
        // supplied later by the typed observation mapper, not copied from RPC.
        messages: Vec::new(),
        artifacts: Vec::new(),
        agent_id: Some(agent_id.to_string()),
        caller_a2a_agent_id: Some(selected.verified_subject.clone()),
    };
    let reserved = store.reserve_uar_job_attempt(reservation, task, pending)
        .map_err(storage_error)?;
    if reserved.disposition == UarReservationDisposition::Existing {
        return reconcile(store, &selected.control, reserved).await;
    }
    // This is the only admission call. Dropping this future after reservation
    // (including before POST) leaves an original unresolved attempt to reconcile.
    let projection = match selected.control.admit_selected(
        &selected.admission, &prepared, preflight, &reserved.projection,
    ).await {
        Ok(mut receipt) => {
            // Admission acknowledgement is not proof that no effect occurred.
            if receipt.admission_state != "refused" {
                receipt.effect_state = "effect_unconfirmed".into();
            }
            receipt
        }
        Err(error) => unknown_projection(reserved.projection.clone(), &error),
    };
    persist(store, &reserved.reservation, projection)
}

fn validate_identity(selected: &SelectedUarJob) -> Result<(), JobDispatchError> {
    if selected.job.selected_task_id().as_deref() != Some(selected.admission.boss_task_id.as_str())
        || selected.verified_subject.trim().is_empty()
        || selected.verified_subject == "anonymous"
        || selected.verified_tenant.as_ref().is_some_and(|value| value.trim().is_empty())
        || selected.job.job_id.trim().is_empty()
        || selected.admission.boss_task_id.trim().is_empty()
        || selected.admission.workspace_id.trim().is_empty()
        || selected.admission.admission_key.trim().is_empty()
        || selected.admission.delegation_id.trim().is_empty()
    {
        return Err(JobDispatchError::InvalidIdentity);
    }
    Ok(())
}

fn validate_existing(
    selected: &SelectedUarJob, original: &UarReservedJobAttempt,
) -> Result<(), JobDispatchError> {
    let saved = &original.projection;
    if saved.boss_task_id != selected.admission.boss_task_id
        || saved.admission_key != selected.admission.admission_key
        || saved.delegation_id != selected.admission.delegation_id
        || saved.target_binding_id != selected.admission.target_binding_id
        || saved.definition != selected.admission.definition
    {
        return Err(JobDispatchError::IdentityConflict);
    }
    Ok(())
}

fn validate_capabilities(
    selected: &SelectedUarJob, pending: &UarDelegatedRunProjection,
) -> Result<(), JobDispatchError> {
    if selected.requires_steer && pending.unsupported_semantics.iter().any(|v| v == "steer") {
        return Err(JobDispatchError::SteerUnsupported);
    }
    for (index, capability) in selected.required_capabilities.iter().enumerate() {
        if !pending.effective_binding.capabilities.contains(capability) {
            return Err(JobDispatchError::CapabilityMissing(index));
        }
    }
    Ok(())
}

async fn reconcile(
    store: &A2aTaskStore, control: &UarRunControl, original: UarReservedJobAttempt,
) -> Result<UarDelegatedRunProjection, JobDispatchError> {
    if original.projection.admission_state == "refused" {
        return Ok(original.projection);
    }
    let observed = if original.projection.uar_task_id.is_some() {
        control.lookup(&original.projection).await
    } else {
        control.resolve(&original.projection).await
    };
    let projection = match observed {
        Ok(receipt) => receipt,
        Err(error) => unknown_projection(original.projection.clone(), &error),
    };
    persist(store, &original.reservation, projection)
}

fn unknown_projection(
    mut original: UarDelegatedRunProjection, error: &UarRunClientError,
) -> UarDelegatedRunProjection {
    let state = match error {
        UarRunClientError::RecoveryUnsupported { .. } =>
            "recovery_unsupported",
        UarRunClientError::ConnectionReattachmentRequired =>
            "outcome_unknown",
        _ if error.refusal().is_some_and(|refusal| refusal.code == "retention_expired") =>
            "expired",
        _ => "outcome_unknown",
    };
    if original.uar_task_id.is_none() {
        original.admission_state = "unresolved".into();
    }
    original.recovery_state = state.into();
    original.effect_state = "effect_unconfirmed".into();
    original
}

fn strip_untyped_presentation(projection: &mut UarDelegatedRunProjection) {
    // No verified sanitizer/provenance is available for these arbitrary values.
    // They are unavailable in selected history until the mapping/observation
    // owner supplies the approved typed secret-excluded presentation contract.
    projection.definition_diagnostics.clear();
    projection.remote_diagnostics.clear();
    projection.links.clear();
}

fn persist(
    store: &A2aTaskStore, reservation: &UarJobAttemptReservation,
    mut projection: UarDelegatedRunProjection,
) -> Result<UarDelegatedRunProjection, JobDispatchError> {
    // Only fixed codes produced here survive; never persist provider diagnostics.
    let local_code = match projection.recovery_state.as_str() {
        "recovery_unsupported" => Some("uar_runtime_epoch_lost"),
        "outcome_unknown" => Some("uar_attempt_outcome_unknown"),
        "expired" => Some("uar_retention_expired"),
        _ => None,
    };
    strip_untyped_presentation(&mut projection);
    if let Some(code) = local_code {
        projection.remote_diagnostics.push(serde_json::json!({"code": code}));
    }
    store.put_uar_delegation(projection).map_err(storage_error)?;
    // Read back the transaction's projection: receipt cursors must not pretend
    // that presentation events were applied by this admission-only boundary.
    store.get_uar_job_attempt(
        &reservation.verified_subject, reservation.verified_tenant.as_deref(),
        &reservation.workspace_id, &reservation.job,
    ).map_err(storage_error)?.map(|saved| saved.projection)
        .ok_or(JobDispatchError::StorageUnknown)
}

fn storage_error(code: String) -> JobDispatchError {
    match code.as_str() {
        "uar_attempt_identity_conflict" => JobDispatchError::IdentityConflict,
        _ => JobDispatchError::StorageUnknown,
    }
}

//! Durable job lifecycle routing. The task-board intent is authoritative before
//! descriptor/network/model work; private A2A outcomes reconcile separately.
use crate::kernel::{LibreFangKernel, subsystems::mesh::MeshSubsystemApi};
use librefang_memory::task_dispatch::{JobDispatchState, SelectedJobIntent, SelectedReconcile};
use librefang_types::agent::AgentId;

impl LibreFangKernel {
    pub async fn read_job_dispatch_intent(&self, job: &str) -> Result<Option<JobDispatchState>, String> {
        self.memory.substrate.task_read_dispatch_intent(job).await
            .map_err(|_| "job_dispatch_storage_unknown".into())
    }

    /// Reconcile only committed original private outcomes. A scheduler does not
    /// possess the API's retained transport and never reconstructs credentials.
    /// Missing A2A state after intent commit remains unknown, never executable.
    pub async fn reconcile_selected_jobs(&self) -> Result<(), String> {
        let jobs = self.memory.substrate.task_list(None).await
            .map_err(|_| "job_dispatch_storage_unknown".to_string())?;
        for job in jobs {
            let Some(id) = job["id"].as_str() else { continue; };
            if let Some(JobDispatchState::Selected(intent)) = self.read_job_dispatch_intent(id).await? {
                self.reconcile_selected_job(intent).await?;
            }
        }
        Ok(())
    }

    pub(crate) async fn reconcile_selected_job(&self, intent: SelectedJobIntent) -> Result<SelectedReconcile, String> {
        let original = self.a2a_tasks().get_uar_job_attempt(&intent.initiating_owner, None,
            &intent.workspace_id, &intent.job).map_err(|_| "selected_attempt_storage_unknown".to_string())?;
        let Some(original) = original else { return Ok(SelectedReconcile::Unknown); };
        if matches!(original.projection.recovery_state.as_str(),
            "outcome_unknown" | "reconciliation_required" | "recovery_unsupported" | "expired") {
            return Ok(SelectedReconcile::Unknown);
        }
        self.memory.substrate.task_reconcile_selected_outcome(intent,
            original.reservation, original.projection).await
            .map_err(|_| "selected_outcome_reconciliation_unknown".into())
    }

    /// Existing workflow input preserves operator context, with actual claimed
    /// rows appended. The trigger owner never becomes an invented assignee.
    pub(crate) async fn claim_task_workflow_input(&self, job: &str, context: &str) -> Result<Option<String>, String> {
        let row = self.memory.substrate.task_get(job).await
            .map_err(|_| "job_dispatch_storage_unknown".to_string())?;
        let assignee = row.as_ref().and_then(|row| row["assigned_to"].as_str()).unwrap_or("");
        let entry = match assignee.parse::<AgentId>() {
            Ok(id) => self.agents.registry.get(id),
            Err(_) => self.agents.registry.find_by_name(assignee),
        };
        let Some(entry) = entry else { return Err("task_workflow_assignee_mapping_unsupported".into()); };
        Ok(self.claim_native_job_prompt(entry.id, &[job.to_owned()]).await?
            .map(|claimed| format!("{context}\n\n{claimed}")))
    }

    /// Exact IDs come from the typed event/pending rows, never prompt parsing.
    /// None means no new claim, so the caller must not start a targeted loop.
    pub(crate) async fn claim_native_job_prompt(&self, agent: AgentId, jobs: &[String]) -> Result<Option<String>, String> {
        for job in jobs {
            if let Some(JobDispatchState::Selected(intent)) = self.read_job_dispatch_intent(job).await? {
                self.reconcile_selected_job(intent).await?;
            }
        }
        let name = self.agents.registry.get(agent).map(|entry| entry.name.clone());
        let rows = self.memory.substrate.task_claim_native_wake(jobs, &agent.to_string(), name.as_deref()).await
            .map_err(|_| "native_job_claim_unknown".to_string())?;
        if rows.is_empty() { return Ok(None); }
        let data = serde_json::to_string(&rows).map_err(|_| "native_job_claim_encoding_failed".to_string())?;
        Ok(Some(format!("[System] These exact task-board jobs are ALREADY CLAIMED by this agent and in_progress. Execute only these rows, then use task_complete with each exact id. Do not call task_claim or discover other work for this wake.\n{data}")))
    }
}

//! Versioned full-run delegation over UAR's existing native run executor.
//!
//! This adapter owns only process-ephemeral admission and control records. It
//! reserves identities before kernel entry, never logs request material, and
//! delegates all run assembly, tool execution, approval, and cancellation to
//! the native run authorities.

use std::{
    collections::HashMap,
    sync::{Arc, Mutex},
    time::Duration,
};

use axum::http::StatusCode;
use chrono::Utc;
use uuid::Uuid;

use crate::{
    config::RunsConfig,
    uar::{
        domain::runs::RunStatus,
        runtime::{actor::messages::ActorOwner, manager::RunManager},
    },
};

const TASK_PREFIX: &str = "fh";

#[derive(Clone)]
pub struct FullHarnessTaskAuthority {
    manager: Arc<RunManager>,
    runtime_epoch: String,
    retention: RetentionReceipt,
    records: Arc<Mutex<AuthorityRecords>>,
}

#[derive(Debug, Default)]
struct AuthorityRecords {
    tasks: HashMap<String, TaskRecord>,
    admissions: HashMap<(ActorOwner, String, String), AdmissionRecord>,
}

#[derive(Debug)]
struct AdmissionRecord {
    task_id: String,
    digest: String,
}

#[derive(Debug, Clone)]
struct TaskRecord {
    owner: ActorOwner,
    workspace_id: String,
    receipt: TaskReceipt,
    admission_response: Option<TaskReceipt>,
    response_status: StatusCode,
}

enum Reservation {
    New(TaskReceipt),
    Existing(StatusCode, TaskReceipt),
}

impl FullHarnessTaskAuthority {
    pub fn new(manager: Arc<RunManager>, config: RunsConfig) -> Self {
        Self {
            manager,
            runtime_epoch: Uuid::new_v4().simple().to_string(),
            retention: RetentionReceipt {
                mode: "process_ephemeral",
                terminal_ttl_seconds: config.retention_after_terminal_secs,
                terminal_record_cap: config.max_retained_terminal,
            },
            records: Arc::new(Mutex::new(AuthorityRecords::default())),
        }
    }

    pub fn runtime_descriptor(&self) -> RuntimeDescriptor {
        RuntimeDescriptor {
            event_cursor_profile: "contiguous_cursor_frames_v1",
            profile: "full_harness_v1",
            runtime_epoch: self.runtime_epoch.clone(),
            recovery: "unsupported_after_restart",
            retention: self.retention.clone(),
            steer_supported: false,
        }
    }

    fn reserve(
        &self,
        owner: ActorOwner,
        workspace_id: String,
        admission_id: String,
        native_task_id: String,
        digest: String,
    ) -> Result<Reservation, ApiError> {
        self.prune();
        let mut records = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let key = (owner.clone(), workspace_id.clone(), admission_id.clone());
        if let Some(admission) = records.admissions.get(&key) {
            if admission.digest != digest {
                return Err(ApiError::conflict(
                    "admission_digest_conflict",
                    "admission_id is already reserved for a different request",
                    Some(admission.task_id.clone()),
                    Some(admission_id),
                ));
            }
            if let Some(record) = records.tasks.get(&admission.task_id) {
                return Ok(Reservation::Existing(
                    record.response_status,
                    record
                        .admission_response
                        .clone()
                        .unwrap_or_else(|| record.receipt.clone()),
                ));
            }
            return Err(ApiError::gone(
                "retention_expired",
                "the exact admission was retained but its process-ephemeral task receipt expired",
                Some(admission.task_id.clone()),
                Some(admission_id),
            ));
        }
        let task_id = format!(
            "{TASK_PREFIX}-{}-{}",
            self.runtime_epoch,
            Uuid::new_v4().simple()
        );
        let run_id = Uuid::new_v4().to_string();
        let base = "/api/uar/full-harness/v1";
        let receipt = TaskReceipt {
            admission_id: admission_id.clone(),
            task_id: task_id.clone(),
            native_task_id,
            run_id,
            workspace_id: workspace_id.clone(),
            agent_id: None,
            runtime_epoch: self.runtime_epoch.clone(),
            revision: 1,
            cursor: None,
            state: "reserved".to_owned(),
            retention: self.retention.clone(),
            effective_service_binding: None,
            diagnostics: Vec::new(),
            cancellation: CancellationReceipt::default(),
            detached: false,
            detached_observers: Vec::new(),
            created_at: Utc::now(),
            terminal_at: None,
            expires_at: None,
            unsupported_semantics: vec!["steer"],
            links: TaskLinks {
                status: format!("{base}/tasks/{task_id}"),
                stream: format!("{base}/tasks/{task_id}/stream"),
                tool_approval: format!("{base}/tasks/{task_id}/tool-approval"),
                cancel: format!("{base}/tasks/{task_id}/cancel"),
                detach: format!("{base}/tasks/{task_id}/detach"),
                steer: format!("{base}/tasks/{task_id}/steer"),
            },
        };
        records.admissions.insert(
            key,
            AdmissionRecord {
                task_id: task_id.clone(),
                digest: digest.clone(),
            },
        );
        records.tasks.insert(
            task_id,
            TaskRecord {
                owner,
                workspace_id,
                receipt: receipt.clone(),
                admission_response: None,
                response_status: StatusCode::ACCEPTED,
            },
        );
        Ok(Reservation::New(receipt))
    }

    fn update(&self, task_id: &str, update: impl FnOnce(&mut TaskRecord)) {
        if let Some(record) = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .tasks
            .get_mut(task_id)
        {
            let previous = record.receipt.clone();
            update(record);
            if record.receipt != previous {
                record.receipt.revision = record.receipt.revision.saturating_add(1);
            }
        }
    }

    fn freeze_admission_response(&self, task_id: &str) -> Result<TaskReceipt, ApiError> {
        let mut records = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let record = records
            .tasks
            .get_mut(task_id)
            .ok_or_else(|| ApiError::not_found("task_not_found", "task was not found"))?;
        let receipt = record.receipt.clone();
        record.admission_response = Some(receipt.clone());
        Ok(receipt)
    }

    fn owned(
        &self,
        owner: &ActorOwner,
        workspace_id: &str,
        task_id: &str,
    ) -> Result<TaskReceipt, ApiError> {
        self.prune();
        let records = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        if let Some(record) = records.tasks.get(task_id) {
            return if &record.owner == owner && record.workspace_id == workspace_id {
                Ok(record.receipt.clone())
            } else {
                Err(ApiError::not_found("task_not_found", "task was not found"))
            };
        }
        if task_id.starts_with(&format!("{TASK_PREFIX}-"))
            && !task_id.starts_with(&format!("{TASK_PREFIX}-{}-", self.runtime_epoch))
        {
            return Err(ApiError::conflict(
                "recovery_unsupported",
                "task belongs to a prior runtime epoch and this profile does not support restart recovery",
                Some(task_id.to_owned()),
                None,
            ));
        }
        if task_id.starts_with(&format!("{TASK_PREFIX}-{}-", self.runtime_epoch)) {
            if let Some(((record_owner, record_workspace, _), _)) = records
                .admissions
                .iter()
                .find(|(_, admission)| admission.task_id == task_id)
            {
                return if record_owner == owner && record_workspace == workspace_id {
                    Err(ApiError::gone(
                        "retention_expired",
                        "task receipt exceeded the advertised terminal TTL or record cap",
                        Some(task_id.to_owned()),
                        None,
                    ))
                } else {
                    Err(ApiError::not_found("task_not_found", "task was not found"))
                };
            }
            return Err(ApiError::gone(
                "task_unresolved",
                "task identity is in the current runtime epoch but no authoritative record remains",
                Some(task_id.to_owned()),
                None,
            ));
        }
        Err(ApiError::not_found("task_not_found", "task was not found"))
    }

    fn admission(
        &self,
        owner: &ActorOwner,
        workspace_id: &str,
        admission_id: &str,
    ) -> Result<TaskReceipt, ApiError> {
        self.prune();
        let records = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let admission = records
            .admissions
            .get(&(
                owner.clone(),
                workspace_id.to_owned(),
                admission_id.to_owned(),
            ))
            .ok_or_else(|| {
                ApiError::not_found(
                    "task_unresolved",
                    "admission has no authoritative process-local record",
                )
            })?;
        records
            .tasks
            .get(&admission.task_id)
            .map(|record| record.receipt.clone())
            .ok_or_else(|| {
                ApiError::gone(
                    "retention_expired",
                    "admission record exceeded the advertised terminal retention",
                    Some(admission.task_id.clone()),
                    Some(admission_id.to_owned()),
                )
            })
    }

    fn prune(&self) {
        let now = Utc::now();
        let mut records = self
            .records
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let ttl = self.retention.terminal_ttl_seconds as i64;
        let mut terminal = records
            .tasks
            .values()
            .filter_map(|record| {
                record
                    .receipt
                    .terminal_at
                    .as_ref()
                    .map(|at| (record.receipt.task_id.clone(), at.to_owned()))
            })
            .collect::<Vec<_>>();
        terminal.sort_by_key(|(_, at)| at.to_owned());
        let overflow = if self.retention.terminal_record_cap == 0 {
            0
        } else {
            terminal
                .len()
                .saturating_sub(self.retention.terminal_record_cap)
        };
        let expired = terminal
            .into_iter()
            .enumerate()
            .filter(|(index, (_, at))| {
                *index < overflow || now.signed_duration_since(at.to_owned()).num_seconds() >= ttl
            })
            .map(|(_, (id, _))| id)
            .collect::<Vec<_>>();
        for task_id in expired {
            records.tasks.remove(&task_id);
        }
    }

    fn monitor(self: &Arc<Self>, task_id: String, run_id: String) {
        let authority = Arc::clone(self);
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(Duration::from_millis(250)).await;
                let Some(run) = authority.manager.get_run(&run_id).await else {
                    continue;
                };
                let terminal = matches!(
                    &run.status,
                    RunStatus::Done | RunStatus::Error | RunStatus::Cancelled
                );
                let cursor = authority
                    .manager
                    .history_since(&run_id, None)
                    .await
                    .and_then(|events| events.last().map(|event| event.id));
                authority.update(&task_id, |record| {
                    record.receipt.cursor = cursor;
                    record.receipt.state = match &run.status {
                        RunStatus::Pending => "submitted",
                        RunStatus::Running => "working",
                        RunStatus::Paused => "input_required",
                        RunStatus::Done => "completed",
                        RunStatus::Error => "failed",
                        RunStatus::Cancelled => "cancelled",
                    }
                    .to_owned();
                    if terminal {
                        let terminal_at = record
                            .receipt
                            .terminal_at
                            .get_or_insert_with(Utc::now)
                            .to_owned();
                        record.receipt.expires_at = Some(
                            terminal_at
                                + chrono::Duration::seconds(
                                    record.receipt.retention.terminal_ttl_seconds as i64,
                                ),
                        );
                        record.receipt.cancellation.terminal =
                            matches!(&run.status, RunStatus::Cancelled);
                    }
                });
                if terminal {
                    let cleanup_uncertain = authority.manager.history_since(&run_id, None).await.unwrap_or_default().iter().any(|event| matches!(&event.event, crate::uar::domain::events::NormalizedEvent::Error { code, .. } if code.ends_with("cleanup_unconfirmed")));
                    authority.update(&task_id, |record| {
                        record.receipt.cancellation.cleanup_uncertain |= cleanup_uncertain
                    });
                    authority.prune();
                    break;
                }
            }
        });
    }

    pub(crate) fn is_task_id(&self, task_id: &str) -> bool {
        task_id.starts_with(&format!("{TASK_PREFIX}-"))
    }
    pub(crate) async fn a2a_get(
        &self,
        owner: &ActorOwner,
        workspace_id: &str,
        agent_id: &str,
        task_id: &str,
    ) -> Result<crate::uar::api::a2a::types::Task, ApiError> {
        let receipt = self.owned(owner, workspace_id, task_id)?;
        if receipt.agent_id.as_deref() != Some(agent_id) {
            return Err(ApiError::not_found("task_not_found", "task was not found"));
        }
        Ok(project_a2a(agent_id, receipt))
    }
